/**
 * Role changes carry two rules the permission matrix cannot express:
 * nobody may grant a role above their own, and the last owner may not be
 * demoted. Both are checked after `can()` has had its say.
 */
export async function updateMemberRole(
  actor: Actor,
  input: UpdateMemberRoleInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  assertCan(actor, "member:update_role", memberResource(member));

  if (!hasRoleAtLeast(actor.role, input.role)) {
    throw new Error(
      `A ${actor.role} cannot grant the ${input.role} role`,
    );
  }

  await assertLastOwnerRetained(input.orgId, input.memberId, input.role);

  const updated = await memberRepo.updateMemberRole(
    input.orgId,
    input.memberId,
    input.role,
  );

  await emit("member.role_changed", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    from: member.role,
    to: updated.role,
  });

  return updated;
}

/**
 * Removal is a soft delete, and it is subject to the same last-owner rule as a
 * demotion — a removed owner is a demotion to "no role at all".
 */
export async function removeMember(
  actor: Actor,
  input: RemoveMemberInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  assertCan(actor, "member:remove", memberResource(member));

  await assertLastOwnerRetained(input.orgId, input.memberId, "member");

  const removed = await memberRepo.archiveMember(input.orgId, input.memberId);

  await emit("member.removed", {
    ...actorEnvelope(actor),
    memberId: removed.id,
    userId: removed.userId,
  });

  return removed;
}

/** Stores or replaces the scoped absence for one active member. */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);

  if (new Date(input.endsAt).getTime() <= new Date(input.startsAt).getTime()) {
    throw new Error("Absence end must be after its start");
  }

  const member = requireActiveMember(
    await memberRepo.findMember(input.orgId, input.userId),
    input.userId,
  );
  assertCanChangeAbsence(actor, member);

  if (input.delegateUserId === input.userId) {
    throw new Error("A member cannot delegate their absence to themselves");
  }

  if (input.delegateUserId !== null) {
    requireActiveMember(
      await memberRepo.findMember(input.orgId, input.delegateUserId),
      input.delegateUserId,
    );
  }

  return absenceRepo.upsertAbsence(input);
}

/** Clears the target's absence; a missing record is already clear. */
export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  const member = requireActiveMember(await memberRepo.findMember(orgId, userId), userId);
  assertCanChangeAbsence(actor, member);
  await absenceRepo.deleteAbsence(orgId, userId);
}

/** Reads a scheduled or currently active absence, hiding one after its end. */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  requireActiveMember(await memberRepo.findMember(orgId, userId), userId);

  const absence = await absenceRepo.findAbsence(orgId, userId);
  if (
    absence === null ||
    new Date(absence.endsAt).getTime() <= Date.now()
  ) {
    return null;
  }
  return absence;
}

function requireActiveMember(member: Member | null, userId: UserId): Member {
  const active = member?.status === "active" ? member : null;
  return requireFound(active, "Member", userId);
}

/** Self-service is open to every member; managing another member uses the role permission. */
function assertCanChangeAbsence(actor: Actor, member: Member): void {
  if (actor.userId !== member.userId) {
    assertCan(actor, "member:update_role", memberResource(member));
  }
}

